<?php
declare(strict_types=1); namespace TmsAi\Services; use TmsAi\Core\App;
final class ClientKeyService { public function create(string $name):array{$name=trim($name)?:'Default';$plain='tms_'.bin2hex(random_bytes(24));$prefix=substr($plain,0,12);$s=App::db()->prepare('INSERT INTO client_keys(name,key_prefix,key_hash,enabled,created_at) VALUES(:n,:p,:h,1,:t)');$s->bindValue(':n',$name,SQLITE3_TEXT);$s->bindValue(':p',$prefix,SQLITE3_TEXT);$s->bindValue(':h',hash('sha256',$plain),SQLITE3_TEXT);$s->bindValue(':t',time(),SQLITE3_INTEGER);$s->execute();return['id'=>(int)App::db()->lastInsertRowID(),'name'=>$name,'key'=>$plain,'prefix'=>$prefix];} public function all():array{$r=App::db()->query('SELECT id,name,key_prefix,enabled,created_at,last_used_at FROM client_keys ORDER BY id DESC');$o=[];while($x=$r->fetchArray(SQLITE3_ASSOC))$o[]=$x;return$o;} public function revoke(int $id):void{App::db()->exec('UPDATE client_keys SET enabled=0 WHERE id='.max(0,$id));}}
